"""Runtime support for vecDSL programs generated for Qdrant with the qdrant-client SDK. Generated by vecDSL 7. Do not edit."""

from __future__ import annotations

import json
import os
import re
import time
import uuid
from importlib.metadata import PackageNotFoundError, version
from typing import Any, Iterator, NoReturn, Sequence

SDK_PACKAGE = "{{sdk.python.package}}"
SDK_MIN = "{{sdk.python.min}}"
SDK_MAX = "{{sdk.python.max}}"

_PAGE = 256
_BATCH = 100
_DIGITS = 6
_DISTANCES = ("euclidean", "manhattan")
_WAIT = 120.0
_POLL = 0.5
_SNAPSHOTS = "{{snapshots.path}}"
_SNAPSHOT_NAMES = "vecdsl_snapshots"


class UnsupportedFeature(NotImplementedError):
    pass


def _version_tuple(text: str) -> tuple[int, ...]:
    parts = []
    for token in re.split(r"[.+\-]", text.lstrip("v")):
        if not token.isdigit():
            break
        parts.append(int(token))
    return tuple(parts)


def requirement() -> str:
    return f"{SDK_PACKAGE}>={SDK_MIN},<{SDK_MAX}"


def check_sdk() -> str:
    try:
        installed = version(SDK_PACKAGE)
    except PackageNotFoundError as error:
        raise ImportError(f"{SDK_PACKAGE} is not installed; install '{requirement()}'") from error
    if not _version_tuple(SDK_MIN) <= _version_tuple(installed) < _version_tuple(SDK_MAX):
        raise ImportError(f"{SDK_PACKAGE} {installed} is not supported; install '{requirement()}'")
    return installed


check_sdk()

from qdrant_client import QdrantClient, models  # noqa: E402


def unsupported(vendor: str, feature: str) -> NoReturn:
    raise UnsupportedFeature(f"{feature} is not supported for target {vendor}")


def env(name: str) -> str:
    value = os.environ.get(name)
    if value is None:
        raise KeyError(f"environment variable {name} is not set")
    return value


Client = QdrantClient


def connect(uri: str, api_key: str | None = None, grpc_port: int | None = None, timeout: float | None = None) -> Client:
    """REST client; grpc_port is used by the Java runtime, which speaks gRPC."""
    options: dict[str, Any] = {"url": uri, "api_key": api_key or None}
    if timeout is not None:
        options["timeout"] = int(timeout)
    return QdrantClient(**options)


def point_id(key: Any) -> str:
    """Point id of a primary key: UUIDv5 in the DNS namespace of the key's text, as the Weaviate generator derives it."""
    if isinstance(key, bool) or not isinstance(key, (int, float, str)):
        raise TypeError(f"cannot use {key!r} as a Qdrant primary key")
    if isinstance(key, float):
        if not key.is_integer():
            raise TypeError(f"cannot use {key!r} as a Qdrant primary key")
        key = int(key)
    return str(uuid.uuid5(uuid.NAMESPACE_DNS, str(key)))


def _value(value: Any) -> Any:
    """Result values in one form for every host language: floats rounded, integral floats as integers."""
    if isinstance(value, float):
        rounded = round(value, _DIGITS)
        return int(rounded) if rounded.is_integer() else rounded
    if isinstance(value, (list, tuple)):
        return [_value(item) for item in value]
    if isinstance(value, dict):
        return {key: _value(item) for key, item in value.items()}
    return value


def _chunks(items: Sequence[Any], size: int) -> Iterator[Sequence[Any]]:
    for start in range(0, len(items), size):
        yield items[start:start + size]


def _filter(where: dict[str, Any] | None) -> models.Filter | None:
    return None if where is None else models.Filter.model_validate(where)


def _consistency(collection: dict[str, Any]) -> Any:
    level = collection.get("read_consistency")
    return None if level is None else models.ReadConsistencyType(level)


def _ordering(collection: dict[str, Any], ordering: str | None) -> Any:
    level = ordering or collection.get("ordering")
    return None if level is None else models.WriteOrdering(level)


def _shards(shard_key: Any) -> Any:
    """Shard key selector of a statement's partitions (custom sharding); None reads every shard."""
    if shard_key is None:
        return None
    return list(shard_key) if isinstance(shard_key, (list, tuple)) else shard_key


def _poll(ready: Any, what: str, timeout: float = _WAIT) -> Any:
    """Calls ready() until it returns a value other than None or False; raises after the timeout."""
    deadline = time.monotonic() + timeout
    while True:
        result = ready()
        if result is not None and result is not False:
            return result
        if time.monotonic() > deadline:
            raise TimeoutError(f"{what} did not finish within {timeout:g} s")
        time.sleep(_POLL)


# ---------------------------------------------------------------- collections

_INDEXES: dict[str, Any] = {
    "keyword": models.KeywordIndexParams, "integer": models.IntegerIndexParams, "float": models.FloatIndexParams,
    "bool": models.BoolIndexParams, "datetime": models.DatetimeIndexParams, "uuid": models.UuidIndexParams,
    "geo": models.GeoIndexParams, "text": models.TextIndexParams,
}


def has_collection(client: Client, name: str) -> bool:
    return client.collection_exists(name)


def drop_collection(client: Client, name: str) -> None:
    client.delete_collection(name)


def create_collection(client: Client, name: str, vectors: dict[str, Any] | None = None,
                      sparse_vectors: dict[str, Any] | None = None, indexes: Sequence[dict[str, Any]] = (),
                      optimizers: dict[str, Any] | None = None, strict_mode: bool | None = None,
                      metadata: dict[str, Any] | None = None, aliases: Sequence[str] = (),
                      replication_factor: int | None = None, shard_number: int | None = None,
                      payload: dict[str, Any] | None = None, sharding_method: str | None = None,
                      shard_keys: Sequence[str] = ()) -> None:
    options: dict[str, Any] = {
        "collection_name": name,
        "vectors_config": {field: models.VectorParams.model_validate(params) for field, params in (vectors or {}).items()},
    }
    if replication_factor is not None:
        options["replication_factor"] = int(replication_factor)
    if shard_number is not None:
        options["shard_number"] = int(shard_number)
    if sharding_method is not None:
        options["sharding_method"] = models.ShardingMethod(sharding_method)
    if payload is not None:
        options["payload"] = models.PayloadStorageParams.model_validate(payload)
    if sparse_vectors:
        options["sparse_vectors_config"] = {field: models.SparseVectorParams.model_validate(params)
                                            for field, params in sparse_vectors.items()}
    if optimizers:
        options["optimizers_config"] = models.OptimizersConfigDiff.model_validate(optimizers)
    if strict_mode is not None:
        options["strict_mode_config"] = models.StrictModeConfig(enabled=strict_mode)
    if metadata:
        options["metadata"] = metadata
    client.create_collection(**options)
    for shard_key in shard_keys:
        create_shard_key(client, name, shard_key)
    for index in indexes:
        create_payload_index(client, name, index["field"], index["schema"])
    for alias in aliases:
        create_alias(client, alias, name)


def create_payload_index(client: Client, name: str, field: str, schema: dict[str, Any]) -> None:
    client.create_payload_index(name, field_name=field, field_schema=_INDEXES[schema["type"]].model_validate(schema), wait=True)


def create_alias(client: Client, alias: str, collection: str) -> None:
    client.update_collection_aliases(change_aliases_operations=[
        models.CreateAliasOperation(create_alias=models.CreateAlias(collection_name=collection, alias_name=alias))])


def swap_alias(client: Client, alias: str, collection: str) -> None:
    """Points an alias at another collection in one request: delete and create are applied together."""
    client.update_collection_aliases(change_aliases_operations=[
        models.DeleteAliasOperation(delete_alias=models.DeleteAlias(alias_name=alias)),
        models.CreateAliasOperation(create_alias=models.CreateAlias(collection_name=collection, alias_name=alias))])


# ---------------------------------------------------------------- writes

def _check(collection: dict[str, Any], record: dict[str, Any]) -> None:
    for field, limit in collection.get("limits", {}).items():
        value = record.get(field)
        if value is None:
            continue
        if "max_items" in limit and len(value) > limit["max_items"]:
            raise ValueError(f"{field} has {len(value)} items; at most {limit['max_items']} are allowed")
        if "max_length" in limit:
            for text in value if isinstance(value, list) else [value]:
                if isinstance(text, str) and len(text) > limit["max_length"]:
                    raise ValueError(f"{field} is longer than {limit['max_length']} characters")


def _typed(collection: dict[str, Any], name: str, value: Any) -> Any:
    """Integral floats of integer fields as integers: Qdrant matches integers only against integer payload values."""
    if name in collection.get("integers", ()) and isinstance(value, float) and value.is_integer():
        return int(value)
    return value


def _vector(value: Any) -> Any:
    if isinstance(value, dict):
        return models.SparseVector(indices=[int(i) for i in value["indices"]], values=[float(v) for v in value["values"]])
    if value and isinstance(value[0], (list, tuple)):
        return [[float(x) for x in row] for row in value]
    return [float(x) for x in value]


def _split(collection: dict[str, Any], record: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any]]:
    """Payload and named vectors of a record; Qdrant stores no nulls here, so absent and null are the same."""
    _check(collection, record)
    vectors = set(collection.get("vectors", ()))
    payload = {name: _typed(collection, name, value) for name, value in record.items()
               if value is not None and name not in vectors}
    named = {name: _vector(value) for name, value in record.items() if value is not None and name in vectors}
    return payload, named


def _point(collection: dict[str, Any], row: dict[str, Any], slice: dict[str, Any] | None = None) -> models.PointStruct:
    """A point of a record; slice holds the tenant and namespace payload values of the write."""
    record = {**collection.get("defaults", {}), **row, **(slice or {})}
    key = record.get(collection["key"])
    if key is None:
        raise ValueError(f"record without primary key {collection['key']}: {row}")
    payload, named = _split(collection, record)
    return models.PointStruct(id=point_id(key), vector=named, payload=payload)


def _existing(client: Client, collection: dict[str, Any], ids: Sequence[str], shard_key: Any = None) -> set[str]:
    found: set[str] = set()
    for chunk in _chunks(list(ids), _PAGE):
        records = client.retrieve(collection["name"], ids=list(chunk), with_payload=False, with_vectors=False,
                                  consistency=_consistency(collection), shard_key_selector=_shards(shard_key))
        found.update(str(record.id) for record in records)
    return found


def _pages(client: Client, collection: dict[str, Any], where: dict[str, Any] | None, payload: Any,
           vectors: Any, shard_key: Any = None) -> Iterator[Any]:
    """Every point that matches a filter, through paginated scrolls; a repeated page offset ends the scroll."""
    offset: Any = None
    seen: set[str] = set()
    while True:
        records, offset = client.scroll(collection["name"], scroll_filter=_filter(where), limit=_PAGE, offset=offset,
                                        with_payload=payload, with_vectors=vectors, consistency=_consistency(collection),
                                        shard_key_selector=_shards(shard_key))
        yield from records
        if offset is None or str(offset) in seen:
            return
        seen.add(str(offset))


def _matching(client: Client, collection: dict[str, Any], where: dict[str, Any] | None, shard_key: Any = None) -> list[str]:
    """Ids of every point that matches a filter."""
    return [str(record.id) for record in _pages(client, collection, where, False, False, shard_key)]


def _targets(client: Client, collection: dict[str, Any], ids: Sequence[Any] | None,
             filter: dict[str, Any] | None, shard_key: Any = None) -> list[str]:
    if ids:
        wanted = list(dict.fromkeys(point_id(key) for key in ids))
        if filter is not None:
            selected = {"must": [{"has_id": wanted}, filter]}
            matching = set(_matching(client, collection, selected, shard_key))
            return [pid for pid in wanted if pid in matching]
        existing = _existing(client, collection, wanted, shard_key)
        return [pid for pid in wanted if pid in existing]
    if filter is not None:
        return _matching(client, collection, filter, shard_key)
    raise ValueError("the statement selects no records")


def _upsert(client: Client, collection: dict[str, Any], points: Sequence[models.PointStruct], batch_size: int,
            wait: bool, ordering: str | None, mode: Any = None, shard_key: Any = None) -> None:
    for chunk in _chunks(list(points), batch_size):
        client.upsert(collection["name"], points=list(chunk), wait=wait, ordering=_ordering(collection, ordering),
                      update_mode=mode, shard_key_selector=_shards(shard_key))


def insert_rows(client: Client, collection: dict[str, Any], rows: Sequence[dict[str, Any]], on_conflict: str = "error",
                batch_size: int = _BATCH, wait: bool = False, ordering: str | None = None,
                slice: dict[str, Any] | None = None, shard_key: Any = None) -> dict[str, int]:
    points = [_point(collection, row, slice) for row in rows]
    existing = _existing(client, collection, [str(point.id) for point in points])
    if existing and on_conflict == "error":
        raise ValueError(f"{len(existing)} records already exist in {collection['name']}")
    fresh = [point for point in points if str(point.id) not in existing]
    _upsert(client, collection, fresh, batch_size, wait, ordering, models.UpdateMode.INSERT_ONLY, shard_key)
    return {"insert_count": len(fresh), "skipped": len(points) - len(fresh)}


def upsert_rows(client: Client, collection: dict[str, Any], rows: Sequence[dict[str, Any]], batch_size: int = _BATCH,
                wait: bool = False, ordering: str | None = None, slice: dict[str, Any] | None = None,
                shard_key: Any = None) -> dict[str, int]:
    points = [_point(collection, row, slice) for row in rows]
    _upsert(client, collection, points, batch_size, wait, ordering, shard_key=shard_key)
    return {"upsert_count": len(points)}


def _arrays(client: Client, collection: dict[str, Any], targets: Sequence[str], items: dict[str, Any],
            append: Sequence[str], remove_items: Sequence[str], write: dict[str, Any]) -> None:
    """array-append and array-remove: each target's stored array with the items appended or removed, written back."""
    fields = [*append, *remove_items]
    for chunk in _chunks(list(targets), _PAGE):
        stored = client.retrieve(collection["name"], ids=list(chunk), with_payload=fields, with_vectors=False)
        for point in stored:
            payload = point.payload or {}
            changed: dict[str, Any] = {}
            for field in append:
                changed[field] = list(payload.get(field) or []) + [_typed(collection, field, x) for x in items.get(field) or []]
            for field in remove_items:
                dropped = [_typed(collection, field, x) for x in items.get(field) or []]
                changed[field] = [x for x in payload.get(field) or [] if x not in dropped]
            _check(collection, changed)
            client.set_payload(collection["name"], payload=changed, points=[point.id], **write)


def update_rows(client: Client, collection: dict[str, Any], ids: Sequence[Any] | None = None,
                filter: dict[str, Any] | None = None, values: dict[str, Any] | None = None,
                rows: Sequence[dict[str, Any]] | None = None, remove: Sequence[str] | None = None,
                mode: str = "merge", wait: bool = False, ordering: str | None = None, shard_key: Any = None,
                append: Sequence[str] = (), remove_items: Sequence[str] = ()) -> dict[str, int]:
    replacements = {point_id(row[collection["key"]]): row for row in rows or []}
    if replacements:
        chosen = {point_id(key) for key in ids or ()}
        targets = [pid for pid in _targets(client, collection, [row[collection["key"]] for row in rows or []], filter, shard_key)
                   if not chosen or pid in chosen]
    elif ids or filter is not None:
        targets = _targets(client, collection, ids, filter, shard_key)
    else:
        raise ValueError("update requires ids, a filter or records")
    write = {"wait": wait, "ordering": _ordering(collection, ordering), "shard_key_selector": _shards(shard_key)}
    name = collection["name"]
    if not replacements and mode != "replace":
        items = {field: (values or {}).get(field) for field in [*append, *remove_items]}
        plain = {field: value for field, value in (values or {}).items() if field not in items}
        payload, named = _split(collection, plain)
        if collection["key"] in payload:
            raise ValueError(f"update cannot change the primary key {collection['key']}")
        if payload and targets:
            client.set_payload(name, payload=payload, points=targets, **write)
        if named and targets:
            client.update_vectors(name, points=[models.PointVectors(id=pid, vector=named) for pid in targets], **write)
        if remove and targets:
            client.delete_payload(name, keys=list(remove), points=targets, **write)
        if items and targets:
            _arrays(client, collection, targets, items, append, remove_items, write)
        return {"update_count": len(targets)}
    for pid in targets:
        record = {**replacements.get(pid, {}), **(values or {})}
        key = record.get(collection["key"])
        if key is not None and point_id(key) != pid:
            raise ValueError(f"update cannot change the primary key {collection['key']}")
        payload, named = _split(collection, record)
        if mode == "replace":
            if collection["key"] not in payload:
                stored = client.retrieve(name, ids=[pid], with_payload=[collection["key"]], with_vectors=False)
                payload[collection["key"]] = stored[0].payload[collection["key"]]
            client.overwrite_payload(name, payload=payload, points=[pid], **write)
        elif payload:
            client.set_payload(name, payload=payload, points=[pid], **write)
        if named:
            client.update_vectors(name, points=[models.PointVectors(id=pid, vector=named)], **write)
        if remove:
            client.delete_payload(name, keys=list(remove), points=[pid], **write)
    return {"update_count": len(targets)}


def _first(client: Client, collection: dict[str, Any], targets: Sequence[str], limit: int) -> list[str]:
    """The first targets in primary key order."""
    keyed: list[tuple[Any, str]] = []
    for chunk in _chunks(list(targets), _PAGE):
        for point in client.retrieve(collection["name"], ids=list(chunk), with_payload=[collection["key"]], with_vectors=False):
            keyed.append(((point.payload or {}).get(collection["key"]), str(point.id)))
    return [pid for _, pid in sorted(keyed)[:limit]]


def delete_rows(client: Client, collection: dict[str, Any], ids: Sequence[Any] | None = None,
                filter: dict[str, Any] | None = None, delete_all: bool = False, wait: bool = False,
                ordering: str | None = None, shard_key: Any = None, limit: int | None = None) -> dict[str, int]:
    write = {"wait": wait, "ordering": _ordering(collection, ordering), "shard_key_selector": _shards(shard_key)}
    if delete_all and limit is None:
        total = count(client, collection, filter, shard_key)
        client.delete(collection["name"], points_selector=models.FilterSelector(filter=_filter(filter) or models.Filter()),
                      **write)
        return {"delete_count": total}
    every = limit is not None and not ids and filter is None
    targets = _targets(client, collection, ids, {} if every else filter, shard_key)
    if limit is not None:
        targets = _first(client, collection, targets, limit)
    for chunk in _chunks(targets, _PAGE):
        client.delete(collection["name"], points_selector=models.PointIdsList(points=list(chunk)), **write)
    return {"delete_count": len(targets)}


# ---------------------------------------------------------------- reads

def _payload(collection: dict[str, Any], output: Sequence[str]) -> list[str]:
    return list(dict.fromkeys([collection["key"], *output]))


def _with_vectors(vectors: Sequence[str] | None) -> Any:
    return list(vectors) if vectors else False


def _row(collection: dict[str, Any], point: Any, output: Sequence[str], vectors: Sequence[str] | None) -> dict[str, Any]:
    payload = point.payload or {}
    row = {collection["key"]: payload.get(collection["key"])}
    for name in output:
        row[name] = _value(payload.get(name))
    stored = point.vector if isinstance(point.vector, dict) else {}
    for name in vectors or ():
        vector = stored.get(name)
        if isinstance(vector, models.SparseVector):
            vector = {"indices": list(vector.indices), "values": list(vector.values)}
        row[name] = _value(vector)
    return row


def get_rows(client: Client, collection: dict[str, Any], ids: Sequence[Any], output: Sequence[str],
             vectors: Sequence[str] | None = None, filter: dict[str, Any] | None = None,
             shard_key: Any = None) -> list[dict[str, Any]]:
    """Records by primary key; a tenant or namespace filter restricts them to its slice."""
    wanted = list(dict.fromkeys(point_id(key) for key in ids))
    if filter is not None:
        points = _pages(client, collection, {"must": [{"has_id": wanted}, filter]}, _payload(collection, output),
                        _with_vectors(vectors), shard_key)
    else:
        points = client.retrieve(collection["name"], ids=wanted, with_payload=_payload(collection, output),
                                 with_vectors=_with_vectors(vectors), consistency=_consistency(collection),
                                 shard_key_selector=_shards(shard_key))
    found = {str(point.id): point for point in points}
    return [_row(collection, found[pid], output, vectors) for pid in wanted if pid in found]


def count(client: Client, collection: dict[str, Any], filter: dict[str, Any] | None = None, shard_key: Any = None) -> int:
    return client.count(collection["name"], count_filter=_filter(filter), exact=True,
                        shard_key_selector=_shards(shard_key)).count


def scroll(client: Client, collection: dict[str, Any], output: Sequence[str], filter: dict[str, Any] | None = None,
           limit: int | None = None, offset: int | None = None, vectors: Sequence[str] | None = None,
           order: dict[str, Any] | None = None, shard_key: Any = None) -> list[dict[str, Any]]:
    """Records in the order of an indexed payload field (the integer key by default), else sorted by key in the runtime."""
    skip = offset or 0
    selected: list[Any] = []
    if order is not None:
        size = count(client, collection, filter, shard_key) if limit is None else skip + limit
        if size == 0:
            return []
        records, _ = client.scroll(collection["name"], scroll_filter=_filter(filter), limit=size,
                                   order_by=models.OrderBy.model_validate(order),
                                   with_payload=_payload(collection, output), with_vectors=_with_vectors(vectors),
                                   consistency=_consistency(collection), shard_key_selector=_shards(shard_key))
        selected = list(records)[skip:]
    else:
        selected = list(_pages(client, collection, filter, _payload(collection, output), _with_vectors(vectors),
                               shard_key))
        selected = sorted(selected, key=lambda point: point.payload[collection["key"]])[skip:]
    if limit is not None:
        selected = selected[:limit]
    return [_row(collection, point, output, vectors) for point in selected]


def similarity(metric: str, score: float) -> float:
    """Canonical similarity of a Qdrant score; Euclid and Manhattan scores are distances."""
    return -score if metric in _DISTANCES else score


def _threshold(metric: str, score_min: float | None) -> float | None:
    """Qdrant's score_threshold for a lower similarity bound: an upper distance bound for Euclid and Manhattan."""
    if score_min is None:
        return None
    return -score_min if metric in _DISTANCES else score_min


def _params(params: dict[str, Any] | None) -> models.SearchParams | None:
    return None if params is None else models.SearchParams.model_validate(params)


def _within(score: float, score_min: float | None, score_max: float | None) -> bool:
    return (score_min is None or score >= score_min) and (score_max is None or score <= score_max)


def _hit(collection: dict[str, Any], point: Any, score: float, output: Sequence[str],
         vectors: Sequence[str] | None) -> dict[str, Any]:
    row = _row(collection, point, output, vectors)
    return {"id": row.pop(collection["key"]), "score": _value(float(score)), **row}


def _hits(collection: dict[str, Any], points: Sequence[Any], scores: Sequence[float], output: Sequence[str],
          vectors: Sequence[str] | None, score_min: float | None, score_max: float | None) -> list[dict[str, Any]]:
    return [_hit(collection, point, score, output, vectors) for point, score in zip(points, scores)
            if _within(score, score_min, score_max)]


def _lookup(collection: dict[str, Any], lookup: str | None, field: str) -> models.LookupLocation | None:
    if lookup is None or lookup == collection["name"]:
        return None
    return models.LookupLocation(collection=lookup, vector=field)


def vector_search(client: Client, collection: dict[str, Any], field: str, vector: Sequence[float], limit: int,
                  metric: str, output: Sequence[str], filter: dict[str, Any] | None = None, offset: int | None = None,
                  score_min: float | None = None, score_max: float | None = None, native: bool = False,
                  vectors: Sequence[str] | None = None, params: dict[str, Any] | None = None, mmr: dict[str, Any] | None = None,
                  prefetch: Sequence[dict[str, Any]] | None = None, shard_key: Any = None, group_by: str | None = None,
                  group_size: int | None = None) -> list[dict[str, Any]]:
    """Nearest-neighbour query, with Qdrant's MMR re-ranking, prefetch stages and point groups when given."""
    query: Any = _vector(vector)
    if mmr is not None:
        query = models.NearestQuery(nearest=query, mmr=models.Mmr.model_validate(mmr))
    options: dict[str, Any] = {
        "query": query, "using": field, "query_filter": _filter(filter), "limit": limit,
        "prefetch": [models.Prefetch.model_validate(stage) for stage in prefetch] if prefetch else None,
        "search_params": _params(params), "with_payload": _payload(collection, output),
        "with_vectors": _with_vectors(vectors), "score_threshold": None if native else _threshold(metric, score_min),
        "consistency": _consistency(collection), "shard_key_selector": _shards(shard_key)}
    if group_by is not None:
        groups = client.query_points_groups(collection["name"], group_by=group_by, group_size=group_size, **options).groups
        return [{"group": _value(group.id), "hits": _hits(
            collection, group.hits, [float(p.score) if native else similarity(metric, float(p.score)) for p in group.hits],
            output, vectors, score_min, score_max)} for group in groups]
    response = client.query_points(collection["name"], offset=offset, **options)
    points = response.points
    scores = [float(p.score) if native else similarity(metric, float(p.score)) for p in points]
    return _hits(collection, points, scores, output, vectors, score_min, score_max)


def _text(query: str, bm25: dict[str, Any] | None) -> models.TextQuery:
    if bm25:
        return models.TextQuery(text=models.TextQueryInput(query=query, scoring=models.Bm25Scoring(
            bm25=models.Bm25Params.model_validate(bm25))))
    return models.TextQuery(text=query)


def keyword_search(client: Client, collection: dict[str, Any], query: str, field: str, limit: int,
                   output: Sequence[str], filter: dict[str, Any] | None = None, offset: int | None = None,
                   bm25: dict[str, Any] | None = None, score_min: float | None = None, score_max: float | None = None,
                   vectors: Sequence[str] | None = None, shard_key: Any = None) -> list[dict[str, Any]]:
    response = client.query_points(
        collection["name"], query=_text(query, bm25), using=field, query_filter=_filter(filter), limit=limit,
        offset=offset, with_payload=_payload(collection, output), with_vectors=_with_vectors(vectors),
        score_threshold=score_min, consistency=_consistency(collection), shard_key_selector=_shards(shard_key))
    points = response.points
    return _hits(collection, points, [float(p.score) for p in points], output, vectors, score_min, score_max)


def _leg_query(leg: dict[str, Any]) -> dict[str, Any]:
    """One hybrid leg as a Qdrant query request: a nearest-vector or a BM25 text query with its own filter and limit."""
    request: dict[str, Any] = {"using": leg["field"], "limit": leg["limit"]}
    if leg["kind"] == "vector":
        request["query"] = _vector(leg["vector"])
        request["score_threshold"] = _threshold(leg["metric"], leg.get("score_min"))
        if leg.get("params") is not None:
            request["params"] = _params(leg["params"])
    else:
        request["query"] = _text(leg["query"], leg.get("bm25"))
    if leg.get("filter") is not None:
        request["filter"] = _filter(leg["filter"])
    return request


def _legs(legs: Sequence[dict[str, Any]], limit: int, offset: int | None) -> list[dict[str, Any]]:
    return [{**leg, "limit": int(leg.get("limit", limit + (offset or 0)))} for leg in legs]


def _fused(fusion: str, weight: float, ranked: list[tuple[str, float]]) -> dict[str, float]:
    """Contribution of one leg: weight * similarity, or weight * min-max normalized score."""
    if fusion == "weighted":
        return {pid: weight * score for pid, score in ranked}
    low = min((score for _, score in ranked), default=0.0)
    high = max((score for _, score in ranked), default=0.0)
    return {pid: weight * ((score - low) / (high - low) if high > low else 1.0) for pid, score in ranked}


def hybrid_search(client: Client, collection: dict[str, Any], legs: Sequence[dict[str, Any]], limit: int, fusion: str,
                  output: Sequence[str], k: int = 60, offset: int | None = None, score_min: float | None = None,
                  score_max: float | None = None, vectors: Sequence[str] | None = None,
                  shard_key: Any = None) -> list[dict[str, Any]]:
    """rrf fuses on the server; weighted and relative_score fuse one batched request per leg in the runtime."""
    sized = _legs(legs, limit, offset)
    payload = _payload(collection, output)
    if fusion == "rrf":
        response = client.query_points(
            collection["name"], prefetch=[models.Prefetch(**_leg_query(leg)) for leg in sized],
            query=models.RrfQuery(rrf=models.Rrf(k=int(k) + 1)), limit=limit, offset=offset, with_payload=payload,
            with_vectors=_with_vectors(vectors), consistency=_consistency(collection),
            shard_key_selector=_shards(shard_key))
        points = response.points
        return _hits(collection, points, [float(p.score) for p in points], output, vectors, score_min, score_max)
    requests = [models.QueryRequest(**_leg_query(leg), with_payload=payload, with_vector=_with_vectors(vectors),
                                    shard_key=_shards(shard_key)) for leg in sized]
    responses = client.query_batch_points(collection["name"], requests=requests, consistency=_consistency(collection))
    totals: dict[str, float] = {}
    found: dict[str, Any] = {}
    for leg, response in zip(sized, responses):
        ranked = []
        for point in response.points:
            score = similarity(leg["metric"], float(point.score)) if leg["kind"] == "vector" else float(point.score)
            if leg["kind"] == "vector" and not _within(score, leg.get("score_min"), leg.get("score_max")):
                continue
            found.setdefault(str(point.id), point)
            ranked.append((str(point.id), score))
        for pid, part in _fused(fusion, float(leg.get("weight", 1.0)), ranked).items():
            totals[pid] = totals.get(pid, 0.0) + part
    ranking = sorted(totals, key=lambda pid: (-totals[pid], found[pid].payload[collection["key"]]))
    page = ranking[offset or 0:(offset or 0) + limit]
    return _hits(collection, [found[pid] for pid in page], [totals[pid] for pid in page], output, vectors,
                 score_min, score_max)


def recommend(client: Client, collection: dict[str, Any], field: str, positives: Sequence[Any], limit: int,
              metric: str, output: Sequence[str], negatives: Sequence[Any] = (), lookup: str | None = None,
              filter: dict[str, Any] | None = None, offset: int | None = None, score_min: float | None = None,
              score_max: float | None = None, native: bool = False, vectors: Sequence[str] | None = None,
              params: dict[str, Any] | None = None, shard_key: Any = None) -> list[dict[str, Any]]:
    """Qdrant's average_vector strategy, avg(positive) + avg(positive) - avg(negative); example points are not returned."""
    def example(item: Any) -> Any:
        return _vector(item) if isinstance(item, (list, tuple)) else point_id(item)

    query = models.RecommendQuery(recommend=models.RecommendInput(
        positive=[example(item) for item in positives], negative=[example(item) for item in negatives] or None,
        strategy=models.RecommendStrategy.AVERAGE_VECTOR))
    response = client.query_points(
        collection["name"], query=query, using=field, lookup_from=_lookup(collection, lookup, field),
        query_filter=_filter(filter), limit=limit, offset=offset, search_params=_params(params),
        with_payload=_payload(collection, output), with_vectors=_with_vectors(vectors),
        score_threshold=None if native else _threshold(metric, score_min), consistency=_consistency(collection),
        shard_key_selector=_shards(shard_key))
    points = response.points
    scores = [float(p.score) if native else similarity(metric, float(p.score)) for p in points]
    return _hits(collection, points, scores, output, vectors, score_min, score_max)


def discover(client: Client, collection: dict[str, Any], field: str, context: Sequence[dict[str, Any]], limit: int,
             output: Sequence[str], target: Any = None, filter: dict[str, Any] | None = None, offset: int | None = None,
             score_min: float | None = None, score_max: float | None = None, vectors: Sequence[str] | None = None,
             params: dict[str, Any] | None = None, shard_key: Any = None) -> list[dict[str, Any]]:
    """Discovery (with a target) or context search (without); the scores are Qdrant's own, so 'score native' is required."""
    def example(item: Any) -> Any:
        return _vector(item) if isinstance(item, (list, tuple)) else point_id(item)

    pairs = [models.ContextPair(positive=example(pair["positive"]), negative=example(pair["negative"])) for pair in context]
    query: Any = models.ContextQuery(context=pairs) if target is None else \
        models.DiscoverQuery(discover=models.DiscoverInput(target=example(target), context=pairs))
    response = client.query_points(
        collection["name"], query=query, using=field, query_filter=_filter(filter), limit=limit, offset=offset,
        search_params=_params(params), with_payload=_payload(collection, output), with_vectors=_with_vectors(vectors),
        consistency=_consistency(collection), shard_key_selector=_shards(shard_key))
    points = response.points
    return _hits(collection, points, [float(p.score) for p in points], output, vectors, score_min, score_max)


def lookup_vector(client: Client, collection: dict[str, Any], field: str, id: Any) -> list[float]:
    records = client.retrieve(collection["name"], ids=[point_id(id)], with_payload=False, with_vectors=[field],
                              consistency=_consistency(collection))
    if not records:
        raise KeyError(f"record {id!r} not found in {collection['name']}")
    return [float(x) for x in records[0].vector[field]]


# ---------------------------------------------------------------- schema changes

def require_collection(client: Client, name: str) -> None:
    """The collection must exist; Qdrant serves every collection and payloads are schemaless, so nothing else is due."""
    if not client.collection_exists(name):
        raise KeyError(f"collection {name} does not exist")


def alter_collection(client: Client, name: str, vectors: dict[str, Any] | None = None,
                     sparse_vectors: dict[str, Any] | None = None, hnsw: dict[str, Any] | None = None,
                     quantization: dict[str, Any] | None = None, optimizers: dict[str, Any] | None = None,
                     params: dict[str, Any] | None = None, strict_mode: dict[str, Any] | None = None,
                     metadata: dict[str, Any] | None = None) -> None:
    """Qdrant's collection update (PATCH /collections/{name}): only the parts given change."""
    options: dict[str, Any] = {"collection_name": name}
    if vectors:
        options["vectors_config"] = {field: models.VectorParamsDiff.model_validate(diff) for field, diff in vectors.items()}
    if sparse_vectors:
        options["sparse_vectors_config"] = {field: models.SparseVectorParams.model_validate(diff)
                                            for field, diff in sparse_vectors.items()}
    if hnsw is not None:
        options["hnsw_config"] = models.HnswConfigDiff.model_validate(hnsw)
    if quantization is not None:
        options["quantization_config"] = models.UpdateCollection.model_validate(
            {"quantization_config": quantization}).quantization_config
    if optimizers is not None:
        options["optimizers_config"] = models.OptimizersConfigDiff.model_validate(optimizers)
    if params is not None:
        options["collection_params"] = models.CollectionParamsDiff.model_validate(params)
    if strict_mode is not None:
        options["strict_mode_config"] = models.StrictModeConfig.model_validate(strict_mode)
    if metadata is not None:
        options["metadata"] = metadata
    client.update_collection(**options)


_VECTOR_NAME_KEYS = ("size", "distance", "multivector_config", "datatype", "modifier")


def create_vector(client: Client, name: str, field: str, dense: dict[str, Any] | None = None,
                  sparse: dict[str, Any] | None = None) -> None:
    """A named vector added to an existing collection (Qdrant 1.20); its index, quantization and memory settings follow
    as a collection update. Existing points have no value for it."""
    params = dense if sparse is None else sparse
    created = {key: value for key, value in params.items() if key in _VECTOR_NAME_KEYS}
    rest = {key: value for key, value in params.items() if key not in _VECTOR_NAME_KEYS}
    config: Any = models.DenseVectorNameConfig(dense=models.DenseVectorConfig.model_validate(created)) if sparse is None \
        else models.SparseVectorNameConfig(sparse=models.SparseVectorConfig.model_validate(created))
    client.create_vector_name(name, vector_name=field, vector_name_config=config, wait=True)
    if rest:
        alter_collection(client, name, **({"vectors": {field: rest}} if sparse is None else {"sparse_vectors": {field: rest}}))


def drop_vector(client: Client, name: str, field: str) -> None:
    client.delete_vector_name(name, vector_name=field, wait=True)


def drop_payload_index(client: Client, name: str, field: str) -> None:
    client.delete_payload_index(name, field_name=field, wait=True)


def _indexed(client: Client, name: str) -> dict[str, Any]:
    """Payload indexes of a collection by field: the index schema as JSON."""
    schema = client.get_collection(name).payload_schema or {}
    result: dict[str, Any] = {}
    for field, info in schema.items():
        params = info.params.model_dump(mode="json", exclude_none=True) if info.params is not None else {}
        result[field] = {"type": info.data_type.value, **params}
    return result


def fill_field(client: Client, name: str, field: str, value: Any) -> None:
    """A default for an added field: every point without the field gets the value."""
    client.set_payload(name, payload={field: value}, points=models.Filter(must=[models.IsEmptyCondition(
        is_empty=models.PayloadField(key=field))]), wait=True)


def drop_field(client: Client, name: str, field: str) -> None:
    """A payload field removed from every point, with its payload index."""
    if field in _indexed(client, name):
        drop_payload_index(client, name, field)
    client.delete_payload(name, keys=[field], points=models.Filter(), wait=True)


def rename_field(client: Client, collection: dict[str, Any], field: str, new_name: str) -> dict[str, int]:
    """Qdrant cannot rename a payload key: each point's value is copied to the new key, the old key is removed and its
    payload index moves to the new key."""
    name = collection["name"]
    index = _indexed(client, name).get(field)
    moved = 0
    for point in _pages(client, collection, {"must_not": [{"is_empty": {"key": field}}]}, [field], False):
        client.set_payload(name, payload={new_name: (point.payload or {})[field]}, points=[point.id], wait=True)
        moved += 1
    if index is not None:
        create_payload_index(client, name, new_name, index)
        drop_payload_index(client, name, field)
    client.delete_payload(name, keys=[field], points=models.Filter(), wait=True)
    return {"renamed_count": moved}


def drop_alias(client: Client, alias: str) -> None:
    client.update_collection_aliases(change_aliases_operations=[
        models.DeleteAliasOperation(delete_alias=models.DeleteAlias(alias_name=alias))])


def create_shard_key(client: Client, name: str, shard_key: str) -> None:
    client.create_shard_key(name, shard_key=shard_key)


def drop_shard_key(client: Client, name: str, shard_key: str) -> None:
    client.delete_shard_key(name, shard_key=shard_key)


def has_shard_key(client: Client, name: str, shard_key: str) -> bool:
    return any(str(key.key) == shard_key for key in client.list_shard_keys(name).shard_keys or [])


def rename_vector(client: Client, collection: dict[str, Any], field: str, new_name: str) -> dict[str, int]:
    """Qdrant cannot rename a named vector: a vector with the same parameters is added under the new name, every
    point's vector is copied to it, and the old vector is removed."""
    name = collection["name"]
    params = client.get_collection(name).config.params
    sparse = field in (params.sparse_vectors or {})
    config = (params.sparse_vectors if sparse else params.vectors)[field].model_dump(mode="json", exclude_none=True)
    create_vector(client, name, new_name, **({"sparse": config} if sparse else {"dense": config}))
    moved = 0
    for point in _pages(client, collection, None, False, [field]):
        vector = (point.vector or {}).get(field)
        if vector is not None:
            client.update_vectors(name, points=[models.PointVectors(id=point.id, vector={new_name: vector})], wait=True)
            moved += 1
    drop_vector(client, name, field)
    return {"renamed_count": moved}

def rename_collection(client: Client, name: str, new_name: str) -> None:
    """Qdrant cannot rename a collection: it is cloned under the new name, its aliases move, and the old one is dropped."""
    aliases = [alias.alias_name for alias in client.get_collection_aliases(name).aliases]
    clone_collection(client, name, new_name)
    drop_collection(client, name)
    for alias in aliases:
        create_alias(client, alias, new_name)


# ---------------------------------------------------------------- operational

def _info(client: Client, name: str) -> dict[str, Any]:
    return client.get_collection(name).model_dump(mode="json", exclude_none=True)


def _settled(client: Client, name: str) -> bool:
    """No queued updates and no running optimization."""
    info = _info(client, name)
    if (info.get("update_queue") or {}).get("length", 0) > 0:
        return False
    return not client.get_optimizations(name).running and info["status"] == "green"


def flush(client: Client, name: str) -> None:
    """Qdrant acknowledges a write after its WAL entry; this waits until the update queue has applied every write."""
    _poll(lambda: (_info(client, name).get("update_queue") or {}).get("length", 0) == 0, f"flush of {name}")


def compact(client: Client, name: str, segments: int | None = None, wait: bool = True) -> None:
    """Qdrant compacts with its optimizers: an optimizers update (the target segment count, or no change) runs after
    the current optimizations, and the runtime waits until no optimization runs."""
    alter_collection(client, name, optimizers={} if segments is None else {"default_segment_number": segments})
    if wait:
        _poll(lambda: _settled(client, name), f"compaction of {name}")


def describe(client: Client, name: str, stats: bool = False, index_progress: bool = False) -> dict[str, Any]:
    info = _info(client, name)
    params = info["config"]["params"]
    dense = params.get("vectors") or {}
    result: dict[str, Any] = {
        "name": name, "status": info["status"],
        "vectors": [""] if "size" in dense else sorted(dense),
        "sparse_vectors": sorted(params.get("sparse_vectors") or {}),
        "payload_schema": {field: schema["data_type"] for field, schema in sorted((info.get("payload_schema") or {}).items())},
        "metadata": info["config"].get("metadata") or {},
    }
    if stats:
        result.update({"points_count": info.get("points_count", 0), "segments_count": info["segments_count"],
                       "indexed_vectors_count": info.get("indexed_vectors_count", 0)})
    if index_progress:
        result.update({"optimizations_running": len(client.get_optimizations(name).running),
                       "update_queue": (info.get("update_queue") or {}).get("length", 0)})
    return _value(result)


def await_index(client: Client, name: str, field: str, kind: str, state: str = "ready",
                timeout: float = _WAIT) -> str:
    """Index states: a payload index is ready once it is in the payload schema (Qdrant builds it before acknowledging);
    the vector index of a named vector is ready when no update is queued and no optimization runs."""
    def current() -> str:
        if kind == "payload":
            return "ready" if field in _indexed(client, name) else "pending"
        return "ready" if _settled(client, name) else "building"

    if state != "ready":
        return current()
    return _poll(lambda: current() if current() == "ready" else None, f"index {field} of {name}", timeout)


def rebuild_payload_index(client: Client, name: str, field: str) -> None:
    """Drops and recreates a payload index with its stored schema."""
    schema = _indexed(client, name)[field]
    drop_payload_index(client, name, field)
    create_payload_index(client, name, field, schema)


def list_objects(client: Client, kind: str, scope: str | None = None, key: str | None = None,
                 prefix: str | None = None, limit: int | None = None) -> list[Any]:
    """Names of collections, aliases, payload indexes, shard keys, tenant values or snapshots, sorted."""
    if kind == "collections":
        names = [c.name for c in client.get_collections().collections]
    elif kind == "aliases":
        aliases = client.get_collection_aliases(scope) if scope else client.get_aliases()
        names = [alias.alias_name for alias in aliases.aliases]
    elif kind == "indexes":
        names = list(_indexed(client, scope))
    elif kind == "partitions":
        names = [str(key.key) for key in client.list_shard_keys(scope).shard_keys or []]
    elif kind == "slices":
        hits = client.facet(scope, key=key, limit=1_000_000, exact=True).hits
        names = [str(hit.value) for hit in hits]
    elif kind == "snapshots":
        names = list(_snapshot_names(client, scope))
    else:
        raise ValueError(f"cannot list {kind}")
    names = sorted(name for name in names if prefix is None or name.startswith(prefix))
    return names if limit is None else names[:limit]


# ---------------------------------------------------------------- snapshots

def _snapshot_names(client: Client, name: str) -> dict[str, str]:
    """vecDSL snapshot names of a collection and the files Qdrant gave them; Qdrant names snapshots itself, so the
    runtime keeps the names in the collection metadata."""
    files = {snapshot.name for snapshot in client.list_snapshots(name)}
    names = (client.get_collection(name).config.metadata or {}).get(_SNAPSHOT_NAMES) or {}
    return {label: file for label, file in names.items() if file in files}


def _remember(client: Client, name: str, names: dict[str, Any]) -> None:
    client.update_collection(name, metadata={_SNAPSHOT_NAMES: names})


def create_snapshot(client: Client, name: str, snapshot: str, scope: str = "collection") -> dict[str, Any]:
    if scope == "full":
        return {"snapshot": snapshot, "file": client.create_full_snapshot(wait=True).name}
    flush(client, name)
    file = client.create_snapshot(name, wait=True).name
    names = (client.get_collection(name).config.metadata or {}).get(_SNAPSHOT_NAMES) or {}
    _remember(client, name, {**names, snapshot: file})
    return {"snapshot": snapshot, "file": file}


def _snapshot_source(client: Client, snapshot: str, source: str | None) -> str:
    if source is not None:
        return source
    owners = [c.name for c in client.get_collections().collections if snapshot in _snapshot_names(client, c.name)]
    if len(owners) != 1:
        raise KeyError(f"snapshot {snapshot} belongs to {len(owners)} collections; name the collection")
    return owners[0]


def restore_snapshot(client: Client, name: str, snapshot: str, source: str | None = None, location: str | None = None,
                     wait: bool = True) -> dict[str, Any]:
    """Recovery from a snapshot file of the server's snapshots directory, or from a URL. A collection restored from its
    own snapshot is recovered in place and keeps its snapshot names; any other existing target is replaced (Qdrant
    recovers into an existing collection only with the snapshot's vector configuration), and its aliases are kept."""
    if location is None:
        owner = _snapshot_source(client, snapshot, source)
        names = _snapshot_names(client, owner)
        location = f"file://{_SNAPSHOTS}/{owner}/{names[snapshot]}"
    else:
        owner, names = None, {}
    aliases: list[str] = []
    if owner != name and client.collection_exists(name):
        aliases = [alias.alias_name for alias in client.get_collection_aliases(name).aliases]
        drop_collection(client, name)
    client.recover_snapshot(name, location=location, wait=wait)
    for alias in aliases:
        create_alias(client, alias, name)
    if wait and owner == name:
        _remember(client, name, names)
    return {"collection": name, "count": count(client, {"name": name}) if wait else None}


def drop_snapshot(client: Client, snapshot: str, source: str | None = None) -> None:
    owner = _snapshot_source(client, snapshot, source)
    names = _snapshot_names(client, owner)
    client.delete_snapshot(owner, snapshot_name=names[snapshot], wait=True)
    _remember(client, owner, {label: file for label, file in names.items() if label != snapshot})


def clone_collection(client: Client, name: str, target: str) -> dict[str, Any]:
    """A materialized copy: snapshot, recovery under the new name, and removal of the snapshot file."""
    flush(client, name)
    file = client.create_snapshot(name, wait=True).name
    try:
        client.recover_snapshot(target, location=f"file://{_SNAPSHOTS}/{name}/{file}", wait=True)
    finally:
        client.delete_snapshot(name, snapshot_name=file, wait=True)
    if client.get_collection(target).config.metadata:
        _remember(client, target, None)
    return {"collection": target, "count": count(client, {"name": target})}


# ---------------------------------------------------------------- import and sampling

def read_records(client: Client, location: str) -> list[dict[str, Any]]:
    """Records of a local JSON array or JSON Lines file (file:// URI or path)."""
    path = location[len("file://"):] if location.startswith("file://") else location
    with open(path, encoding="utf-8") as source:
        text = source.read()
    if text.lstrip().startswith("["):
        return json.loads(text)
    return [json.loads(line) for line in text.splitlines() if line.strip()]


def import_file(client: Client, collection: dict[str, Any], location: str, on_conflict: str | None = None,
                batch_size: int = _BATCH, wait: bool = True, slice: dict[str, Any] | None = None,
                shard_key: Any = None) -> dict[str, int]:
    """Qdrant has no server-side file import: the runtime reads the file and writes its records in batches."""
    rows = read_records(client, location)
    if on_conflict in ("update", "replace"):
        return upsert_rows(client, collection, rows, batch_size, wait, slice=slice, shard_key=shard_key)
    return insert_rows(client, collection, rows, on_conflict or "error", batch_size, wait, slice=slice, shard_key=shard_key)


def sample_rows(client: Client, collection: dict[str, Any], size: int, output: Sequence[str], first: bool = False,
                filter: dict[str, Any] | None = None, shard_key: Any = None) -> list[dict[str, Any]]:
    """Qdrant's random sample query, or the first records in primary key order."""
    if first:
        return scroll(client, collection, output, filter=filter, limit=size, shard_key=shard_key)
    response = client.query_points(collection["name"], query=models.SampleQuery(sample=models.Sample.RANDOM),
                                   query_filter=_filter(filter), limit=size, with_payload=_payload(collection, output),
                                   consistency=_consistency(collection), shard_key_selector=_shards(shard_key))
    return sorted((_row(collection, point, output, None) for point in response.points),
                  key=lambda row: row[collection["key"]])


def distance_matrix(client: Client, collection: dict[str, Any], field: str, metric: str, sample: int = 10,
                    limit: int = 3, filter: dict[str, Any] | None = None, shard_key: Any = None) -> list[dict[str, Any]]:
    """Qdrant's distance matrix (pairs of a random sample and their nearest neighbours) with primary keys and
    canonical similarities, sorted by key."""
    pairs = client.search_matrix_pairs(collection["name"], query_filter=_filter(filter), sample=sample, limit=limit,
                                       using=field, consistency=_consistency(collection),
                                       shard_key_selector=_shards(shard_key)).pairs
    ids = list(dict.fromkeys(str(pid) for pair in pairs for pid in (pair.a, pair.b)))
    keys = {str(p.id): (p.payload or {}).get(collection["key"])
            for p in client.retrieve(collection["name"], ids=ids, with_payload=[collection["key"]])}
    rows = [{"a": keys[str(pair.a)], "b": keys[str(pair.b)], "score": _value(similarity(metric, float(pair.score)))}
            for pair in pairs]
    return sorted(rows, key=lambda row: (row["a"], row["b"]))
